yokla: [
  { s: "Elindeki şemada REV B yazıyor, panonun cebindeki kopyada REV D var. Ne yaparsın?", c: "Elindeki çizim eski; pano en az iki kez değişmiş. REV D çizimini bulup onunla çalışırsın, çünkü eski çizim artık panoda olmayan bir bağlantıyı gösterebilir." },
  { s: "Hiç görmediğin bir markanın kontaktöründe 43-44 ve 61-62 kontakları var. Hangisi NO, hangisi NC?", c: "Son rakamı 3-4 olan 43-44 NO, 1-2 olan 61-62 NC'dir. İlk rakamlar sadece sıra numarasıdır; sistem marka değiştikçe değişmez." },
  { s: "Şemada açık çizilmiş KM1 13-14 kontağını panoda ölçtün, kapalı çıktı. Arıza mı?", c: "Şema dinlenme halini çizer. KM1 o an çekiliyse 13-14'ün kapalı olması normaldir. Önce kontaktörün çekili olup olmadığına bakarsın." },
  { s: "Bir motorun enerjisini kesmeden önce tek hat şemasında neye bakarsın, neden?", c: "Motoru besleyebilecek bütün kaynaklara: şebeke, jeneratör, UPS, varsa ikinci besleme. Birini unutursan kestiğini sandığın panoda enerjiyle karşılaşırsın." },
  { s: "Önceki derslerden: Kumanda 24 V DC. Multimetre AC kademedeyken ölçtün, 0 V gördün. Bu ne anlatır?", c: "Hiçbir şey anlatmaz; ölçüm geçersizdir. Multimetre DC gerilimi AC kademede doğru göstermez. Kademeyi DC'ye alıp tekrar ölçersin (Ders 13)." },
  { s: "Önceki derslerden: Proje planında bir hattın üstünde üç kısa eğik çizgi var. Ne demek?", c: "O hatta üç iletken gidiyor demektir. İletken sayısı çoksa tek eğik çizgi çizilip yanına sayı yazılır (Ders 26)." }
],
